match.line:
case 'export':
  await exportCommand(rest[0], {
    ...common,
    out: args.out,
    frontmatter: args.frontmatter,
    exportLinks: args['export-links'],
    pretty: args.pretty,
  });
  break;

export const exportMarkdown: Pipeline<ExportCtx> = new Pipeline<ExportCtx>()
  .pipe(loadAggregate)
  .pipe(renderMarkdownBody)
  .pipe(maybeApplyFrontmatter);

for (const row of ctx.rawMatches ?? []) {
  const match = row.match ? JSON.parse(row.match) : undefined;
  const step_content = row.step_content ? JSON.parse(row.step_content) : undefined;
  const state: FlowMatchState = {
    flow_match_id: row.flow_match_id,
    flows_id: row.flows_id,
    matches_id: row.matches_id ?? undefined,
    order_index: row.order_index,
    content_kind: row.content_kind,
    content_id: row.content_id,
    updated_at: row.flow_match_updated_at,
    match,
    step_content,
  };
  jp.set(aggregate, P.appendMatch, state);
}

const lang = (grepMeta as { language?: string }).language || 'text';
md += '\n```' + lang + '\n';
ctxLines.forEach((ln: string, idx: number) => {
  const ln_no = startLine + idx;
  const safeLine = String(ln || '').replace(/\r?\n$/, '');
  md += `   ${ln_no}: ${safeLine}\n`;
});
md += '```\n';
